reentrancy.fix_pattern:
function withdraw(uint256 amount) external nonReentrant {
    require(balances[msg.sender] >= amount, "insufficient");
    balances[msg.sender] -= amount;          // effects first
    (bool ok, ) = msg.sender.call{value: amount}(""); // interaction last
    require(ok, "transfer failed");
}

access_control.fix_pattern:
function setFeeRecipient(address r) external onlyOwner {
    require(r != address(0), "zero");
    feeRecipient = r;
    emit FeeRecipientSet(r);
}

privileged_auth.fix_pattern:
function withdraw(uint256 amount) external onlyOwner nonReentrant {
    _withdraw(msg.sender, amount);
}

privileged_change.fix_pattern:
function setOracle(address o) external onlyOwner {
    require(o != address(0), "zero address");
    oracle = o;
    emit OracleSet(o);
}

delegatecall.fix_pattern:
address public immutable implementation;
function _forward(bytes calldata data) internal {
    (bool ok, ) = implementation.delegatecall(data); // fixed, trusted target only
    require(ok);
}

arbitrary_transfer.fix_pattern:
function deposit(uint256 amount) external {
    token.safeTransferFrom(msg.sender, address(this), amount); // 'from' is the caller
    balances[msg.sender] += amount;
}

unchecked_call.fix_pattern:
using SafeERC20 for IERC20;
token.safeTransfer(to, amount);
(bool ok, ) = to.call{value: v}("");
require(ok, "call failed");

